import React, { useMemo, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import NavBar from "../NavBar.jsx";
import BottomNav from "../components/BottomNav.jsx";

const TECHS = [
  { key: "frontend",  name: "Frontend",  emoji: "🎨", tagline: "React • Angular • UI/UX",
    subs: [
      { key: "react",   name: "ReactJS",   hint: "HTML/CSS, JavaScript, React" },
      { key: "angular", name: "Angular",   hint: "HTML/CSS, JavaScript, Angular" },
    ]
  },
  { key: "backend",   name: "Backend",   emoji: "🛠️", tagline: "Node • Python • APIs",
    subs: [
      { key: "node-mongo", name: "NodeJS, MongoDB", hint: "JavaScript, Node, MongoDB" },
      { key: "django",      name: "Django",         hint: "Python, Django" },
    ]
  },
  { key: "fullstack", name: "FullStack Developer", emoji: "🧩", tagline: "MERN • MEAN",
    subs: [
      { key: "mern", name: "MERN",  hint: "Mongo • Express • React • Node" },
      { key: "mean", name: "MEAN",  hint: "Mongo • Express • Angular • Node" },
    ]
  },
  { key: "dsa", name: "Data Structures & Algorithms", emoji: "🧠", tagline: "Java • C++ • Python",
    subs: [
      { key: "dsa-java",   name: "Java",   hint: "DSA with Java" },
      { key: "dsa-cpp",    name: "C++",    hint: "DSA with C++" },
      { key: "dsa-python", name: "Python", hint: "DSA with Python" },
    ]
  },
  { key: "data-analyst", name: "Data Analyst", emoji: "📊", tagline: "Excel • SQL • BI",
    subs: [
      { key: "powerbi", name: "PowerBI", hint: "Excel, Python, SQL, PowerBI" },
      { key: "tableau", name: "Tableau", hint: "Excel, Python, SQL, Tableau" },
    ]
  },
  { key: "machine-learning", name: "Machine Learning", emoji: "🤖", tagline: "sklearn • Stats • SQL",
    subs: [{ key: "ml", name: "Machine Learning", hint: "Py • DS • sklearn • SQL • Math/Stats" }]
  },
  { key: "data-science", name: "Data Science", emoji: "🧪", tagline: "ML • DL • Viz",
    subs: [{ key: "ds", name: "Data Science", hint: "BI (PowerBI/Tableau) • ML • DL" }]
  },
  { key: "devops", name: "DevOps/SRE", emoji: "☁️", tagline: "CI/CD • Docker • K8s",
    subs: [{ key: "devops", name: "DevOps", hint: "CI/CD, Docker, Kubernetes" }]
  },
  { key: "cloud", name: "Cloud Computing", emoji: "🌩️", tagline: "AWS • Azure • GCP",
    subs: [{ key: "cloud", name: "Cloud Computing", hint: "AWS, Azure, GCP" }]
  },
];

const slugify = (s) =>
  (s || "").toLowerCase().replace(/[\(\)]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");

export default function TechnologySelection() {
  const { state } = useLocation();
  const nav = useNavigate();

  const company = state?.company || "Your Company";
  const companySlug = state?.slug || slugify(company);
  const flow = state?.flow || "company"; // "company" | "universal"

  const [selected, setSelected] = useState(null); // { key, label }
  const headline = useMemo(() => `Select your technology for ${company}`, [company]);

  const onContinue = () => {
  if (!selected) return;

  // compute a clean company slug (you already have slugify + companySlug above)
  const nextSlug = companySlug;

  // Always go to SelectPackage first
  nav("/select-package", {
    state: {
      company,
      slug: nextSlug,
      flow,                  // "company" or "universal"
      tech: selected.key,
      techLabel: selected.label,
      // keep any scope hint you carry for bands:
      allType: state?.allType,
      scope: state?.scope,
      origin: "technology-selection",
    },
  });
};

  return (
    <div className="bg-[#0f172a] text-white min-h-screen pb-24">
      <NavBar />
      <div className="pt-20 p-6 max-w-6xl mx-auto">
        {/* Header */}
        <div className="relative overflow-hidden rounded-3xl border border-white/10 bg-white/[0.05] backdrop-blur p-6 md:p-10 mb-8">
          <div className="absolute -top-24 -right-24 w-96 h-96 rounded-full blur-3xl opacity-25"
               style={{ background: "radial-gradient(circle at center, #22c55e, transparent 60%)" }} />
          <p className="text-xs md:text-sm text-white/70">TutorSimula • Technology Selection</p>
          <h1 className="text-3xl md:text-5xl font-extrabold tracking-tight mt-2">{headline}</h1>
          <p className="mt-3 text-white/80">Pick a track (or a sub-track). We’ll tailor drills, examples, and panel focus.</p>
          <div className="mt-4 inline-flex items-center gap-2 text-sm">
            <span className="px-2 py-1 rounded-full bg-white/10 border border-white/10">
              {flow === "universal" ? "Universal Tech Mocks" : company}
            </span>
            <span className="px-2 py-1 rounded-full bg-white/10 border border-white/10">
              {flow === "universal" ? "All Companies" : "Company-Based"}
            </span>
            {selected && (
              <span className="px-2 py-1 rounded-full bg-emerald-500/20 border border-emerald-500/40 text-emerald-300">
                Selected: {selected.label}
              </span>
            )}
          </div>
        </div>

        {/* Tech grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {TECHS.map((t) => {
            const active = selected?.key === t.key;
            return (
              <div
                key={t.key}
                className={`group relative overflow-hidden rounded-2xl border p-6 transition cursor-pointer
                  ${active ? "border-white bg-white text-gray-900" : "border-white/10 bg-white/[0.04] hover:bg-white/10 text-white"}`}
                onClick={() => setSelected({ key: t.key, label: t.name })}
                style={{ backdropFilter: "blur(8px)" }}
              >
                <div className="pointer-events-none absolute -top-20 -right-20 w-56 h-56 rounded-full blur-3xl opacity-20 group-hover:opacity-40 transition"
                     style={{ background: "radial-gradient(circle at center, #22c55e, transparent 60%)" }} />
                <div className="text-3xl">{t.emoji}</div>
                <div className="mt-2 text-xl font-bold">{t.name}</div>
                <div className={`text-sm mt-0.5 ${active ? "text-gray-700" : "text-white/70"}`}>{t.tagline}</div>

                {t.subs?.length ? (
                  <div className="mt-4 grid grid-cols-2 gap-3">
                    {t.subs.map((s) => {
                      const subActive = selected?.key === s.key;
                      return (
                        <button
                          key={s.key}
                          type="button"
                          onClick={(e) => { e.stopPropagation(); setSelected({ key: s.key, label: s.name }); }}
                          className={`relative w-full rounded-xl px-3 py-3 border text-sm text-left transition
                            ${subActive
                              ? "bg-emerald-500/20 border-emerald-400 text-emerald-200"
                              : "bg-black/20 border-white/10 hover:bg-black/30 text-white/90"}`}
                          aria-label={s.name}
                          title={s.hint}
                        >
                          <span className="block font-semibold">{s.name}</span>
                          <span className="block text-[11px] opacity-80">{s.hint}</span>
                          {subActive ? (
                            <span className="absolute -right-1 -top-1 h-5 w-5 rounded-full bg-emerald-400 text-gray-900 text-[11px] grid place-items-center font-bold shadow">
                              ✓
                            </span>
                          ) : null}
                        </button>
                      );
                    })}
                  </div>
                ) : null}
              </div>
            );
          })}
        </div>

        {/* Actions */}
        <div className="mt-7 flex flex-wrap gap-3">
          <button onClick={() => nav(-1)} className="px-5 py-2.5 rounded-full bg-white/10 hover:bg-white/15 border border-white/15">
            Back
          </button>
          <button
            onClick={onContinue}
            disabled={!selected}
            className={`px-6 py-2.5 rounded-full font-semibold ${selected ? "text-gray-900" : "text-white/60"}`}
            style={{ background: selected ? "#22c55e" : "rgba(255,255,255,.12)" }}
            title={selected ? "Continue" : "Pick a technology"}
          >
            Continue to select package →
          </button>
        </div>
      </div>

      <BottomNav />
    </div>
  );
}
